import { useState, useRef, useEffect } from 'react'
import { Container, Button } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import DynamicForm from '../../../../../../components/DynamicForm'
import { AddGopayWrapper, Footer } from './index.style'
import { useUpdateBankAccounts } from '../../BankAccount/state/hooks/useBankAccounts'
import { useHistory } from 'react-router'
import { useErrorContextValue, useResetError, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { BANK_FORM_DATA } from '../../../constants'
import { getErrorMessage } from '../../../../../../helpers/utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useGetBankList } from '../../../../Withdrawal/state/hooks/useWithdraw'

function AddGopayForm () {
  const [number, setNumber] = useState('')
  const [{ getBankListData }, getBankListRequest] = useGetBankList()
  const [{ updateBankAccountData = {} }, updateBankAccounts] = useUpdateBankAccounts()
  const formRef = useRef()
  const history = useHistory()
  const [{ updateBankAccountStatus, updateBankAccountErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ UPDATE_BANK_ACCOUNT_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    getBankListRequest()
  }, [getBankListRequest])

  useEffect(() => {
    if (updateBankAccountStatus === 'success') {
      setToLocalStorage(BANK_FORM_DATA, {
        operation_id: updateBankAccountData?.operation_id,
        bank_id: updateBankAccountData?.bank_id
      })
      history.push('/bank-otp')
      resetError(['updateBankAccountStatus'])
    }
    if (updateBankAccountErrorData) {
      ShowSnackbar.error({
        visible: true,
        text: getErrorMessage(500, updateBankAccountErrorData?.error_code)
      })
      resetError(['updateBankAccountErrorData'])
    }
  }, [updateBankAccountData?.bank_id, history, resetError, updateBankAccountStatus, updateBankAccountData?.operation_id, updateBankAccountErrorData])

  const formData = [
    {
      type: 'text',
      name: 'Gopay',
      title: 'Nama Bank',
      disabled: true,
      defaultValue: 'GoPay'
    },
    {
      type: 'number',
      name: 'number',
      title: 'Nomor Handphone',
      required: true
    }
  ]

  const handleOnchange = (data) => {
    setNumber(data.number)
  }
  const handleSubmit = () => {
    let isValid = false
    const formData = formRef.current.validateFormValues()
    if (formData) {
      isValid = true
    }
    if (isValid) {
      const gopay = getBankListData[0]
      updateBankAccounts({
        holder_id: ((number.charAt(0) === '0') ? '' : ((number.substring(0, 2) === '62') ? '' : '62')) + number,
        bank_code: gopay?.bank_code
      })
    }
  }

  return (
    <Container
      title={LANG_STRINGS.addGopay}
      displayBackButton
      hideBottomTabs
      className='bg-white'
      loader={UPDATE_BANK_ACCOUNT_LOADER}
    >
      <AddGopayWrapper>
        <DynamicForm
          form={formData}
          onChange={handleOnchange}
          ref={formRef}
        />
      </AddGopayWrapper>
      <Footer>
        <Button className='submit-button' onClick={handleSubmit}>
          {LANG_STRINGS.saveNew}
        </Button>
      </Footer>
    </Container>
  )
}

export default AddGopayForm
